/*
 * Prepara lo que va adentro del instalador.
 *
 * 1) Hace una copia limpia del andify.html (sin direcciones de tu red) en build/andify.html.
 * 2) Se asegura de que existan los iconos en la carpeta "build" (sin punto). Si la carpeta
 *    se llamo distinto (por ejemplo ".build") o faltan archivos, los copia o los vuelve a crear,
 *    asi la compilacion no falla por un error de nombres al subir los archivos.
 * No modifica tu andify.html.
 */
const fs = require('fs');
const path = require('path');

const raiz = __dirname;
const build = path.join(raiz, 'build');
fs.mkdirSync(build, { recursive: true });

// ---- iconos ----
const PNG_256 = '';
const PNG_MAC = '';
const PNG_T18 = '';
const PNG_T36 = '';
const PNG_512 = '';

// un .ico puede llevar adentro un PNG de 256x256
function icoDesdePng(png) {
  const cab = Buffer.alloc(22);
  cab.writeUInt16LE(0, 0); cab.writeUInt16LE(1, 2); cab.writeUInt16LE(1, 4);   // cabecera: 1 imagen
  cab[6] = 0; cab[7] = 0;                                                      // 0 = 256 px
  cab.writeUInt16LE(1, 10); cab.writeUInt16LE(32, 12);                         // planos y bits
  cab.writeUInt32LE(png.length, 14); cab.writeUInt32LE(22, 18);                // tamano y posicion
  return Buffer.concat([cab, png]);
}
const generar = {
  'icon.png': () => Buffer.from(PNG_512, 'base64'),
  'tray.png': () => Buffer.from(PNG_512, 'base64'),
  'icon.ico': () => icoDesdePng(Buffer.from(PNG_256, 'base64')),
  'icon-mac.png': () => Buffer.from(PNG_MAC, 'base64'),
  'trayTemplate.png': () => Buffer.from(PNG_T18, 'base64'),
  'trayTemplate@2x.png': () => Buffer.from(PNG_T36, 'base64')
};
const otrasCarpetas = ['.build', 'Build', '.Build', 'builds', 'icons', '.'];
for (const nombre of Object.keys(generar)) {
  const destino = path.join(build, nombre);
  if (fs.existsSync(destino) && fs.statSync(destino).size > 100) continue;
  let origen = null;
  for (const c of otrasCarpetas) {
    const f = path.join(raiz, c, nombre);
    if (f !== destino && fs.existsSync(f) && fs.statSync(f).size > 100) { origen = f; break; }
  }
  if (origen) { fs.copyFileSync(origen, destino); console.log('Icono ' + nombre + ': copiado desde ' + path.relative(raiz, origen)); }
  else { fs.writeFileSync(destino, generar[nombre]()); console.log('Icono ' + nombre + ': no estaba, se volvio a crear'); }
}

// ---- andify.html ----
const candidatos = ['andify.html', '.build/andify.html', 'build/andify.html'];
let origenHtml = null;
for (const c of candidatos) {
  const f = path.join(raiz, c);
  if (fs.existsSync(f) && fs.statSync(f).size > 100000) { origenHtml = f; break; }
}
if (!origenHtml) {
  console.error('No encuentro andify.html en la raiz del repositorio. Subilo junto a package.json.');
  process.exit(1);
}
let s = fs.readFileSync(origenHtml, 'utf8');
const cambios = [
  [/const AI_DEFAULT='[^']*';/, "const AI_DEFAULT='';"],
  [/192\.168\.50\.54/g, '192.168.1.20'],
  [/192\.168\.50\.30/g, '192.168.1.30']
];
for (const [de, a] of cambios) s = s.replace(de, a);
fs.writeFileSync(path.join(build, 'andify.html'), s);

const restos = s.match(/192\.168\.50\.\d+/g);
if (restos) console.warn('Atencion: quedan direcciones de tu red:', [...new Set(restos)].join(', '));
console.log('andify.html preparado para el instalador (' + Math.round(s.length / 1024) + ' KB)');
